   const fill=Math.pow(Math.max(0,dx*.68+up*.73),12)*(night?.05:.22);
   // Static skyline interruptions make the horizon reflection less featureless.
   const skyline=.035+.045*(1+Math.sin(longitude*13)*Math.sin(longitude*7));
